import os
import torch


class Config:
    # --------------------------------------------------------------------------
    # Directory & File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_10"

    # Metadata Paths (Generated by the provided script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Raw Data Paths
    TRAIN_DATA_PATH = os.path.join(INPUT_DIR, "train.csv")
    TEST_DATA_PATH = os.path.join(INPUT_DIR, "test.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Paths
    CACHE_FILE = os.path.join(WORKING_DIR, "processed_data.npz")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_SAVE_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Data Configuration
    # --------------------------------------------------------------------------
    # Feature Definitions
    CAT_FEATURE = "f_27"
    # Continuous features are f_00 to f_30, excluding f_27
    CONT_FEATURES = [f"f_{i:02d}" for i in range(31) if i != 27]

    # Tokenization & Sequence Lengths
    CAT_SEQ_LEN = 10  # Length of string in f_27 (10 characters)
    CONT_SEQ_LEN = 30  # Number of continuous features
    TOTAL_SEQ_LEN = CAT_SEQ_LEN + CONT_SEQ_LEN

    # Vocabulary size for f_27 characters (A-Z).
    # We reserve 0 for padding/unknown if necessary, though data is clean.
    # Mapping: A=1, B=2, ..., Z=26.
    VOCAB_SIZE = 30

    # --------------------------------------------------------------------------
    # Model Architecture: Transformer-ResFunnel Hybrid
    # --------------------------------------------------------------------------
    # Shared Embedding Dimension for both char tokens and projected continuous features
    EMBED_DIM = 64

    # Stage 1: Global Interaction (Transformer)
    TRANSFORMER_DEPTH = 2
    TRANSFORMER_HEADS = 4
    TRANSFORMER_FF_DIM = 128
    TRANSFORMER_DROPOUT = 0.1

    # Stage 2: Deep Backbone (Residual Funnel)
    # Compressing from (TOTAL_SEQ_LEN * EMBED_DIM) down to output
    FUNNEL_STAGES = [512, 256, 128]
    FUNNEL_DROPOUT = 0.38  # Aggressive dropout as per idea
    USE_GLU = True  # Gated Linear Units

    # --------------------------------------------------------------------------
    # Training Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 2048
    NUM_WORKERS = 4

    # Optimization
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2  # High weight decay as per idea

    # Loop Controls
    EPOCHS = 50
    EARLY_STOPPING_PATIENCE = 10

    # Debugging / Development
    DEBUG = False
    MAX_DEBUG_SAMPLES = 10000  # Limit dataset size when DEBUG is True

    # Compute
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """Ensure working directory exists."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
